import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-design-page',
  templateUrl: './design-page.page.html',
  styleUrls: ['./design-page.page.scss'],
})
export class DesignPagePage implements OnInit {

 
  
  accordionState: {}  = {}; 
  selectedYear: number | null = null; 
  currUser:any
  Acdamicyear: any[] = [];
  id: any;
  viewstatus: any;
  acdamicyear: string;
  acdamicyeartopbar: string;
  AcYears: string;
  phaseName: string;


  constructor(private usersessionService: UserSessionService,private userService: UserService,private router: Router) {
    this.currUser = this.usersessionService.emis_username();
    // this.years.forEach(year => {
    //   this.phaseVisibility[year] = false;
    // });
   }

  ngOnInit() {
    this.selectedYear =  null
    this.getacdamicyear()
  }

  toggleAccordion(year: number, index) {
    debugger
    this.Acdamicyear[index]['view'] = !this.Acdamicyear[index]['view'];
    this.selectedYear =  null
    if (this.selectedYear === year) {
      this.selectedYear = null;
    } else {
      this.selectedYear = year;
      Object.keys(this.accordionState).forEach(key => {
        if (parseInt(key) !== year) {
          this.accordionState[parseInt(key)] = false;
        }
      });
      this.accordionState[year] = !this.accordionState[year];
    }
    console.log(this.Acdamicyear,"this.Acdamicyear");
    
  }

  getacdamicyear() {
    this.Acdamicyear = [];
    this.userService.getacdamicdata().subscribe((res: any) => {
      this.Acdamicyear = res.result.map(item => {
        return {
          AcYears: item.AcYears,
          view: false,
          Phase: item.Phase.map(phase => {
            return {
              id: phase.id,
              phaseName: phase.phase ,
              viewstatus:phase.view_status,
            };
          })
        };
      });

      console.log(this.Acdamicyear,"this.Acdamicyear");
      
      
      // Log the retrieved data to the console

      this.id = "id"
      this.viewstatus = "viewstatus"
      this.AcYears = "AcYears";
      this.phaseName = "phaseName"
      
      // this.getawcname(id);
    });
  }

  getawcname(id,viewstatus,phaseName,AcYears){
    debugger
    window.localStorage.setItem("viewstatus", viewstatus);
  this.router.navigate(['/tabs/list-of-awc'],{
    queryParams: { id: id ,viewstatus: viewstatus,phaseName :phaseName,AcYears : AcYears}
    });
   }

onGoButton(){
  this.selectedYear = null
  this.getacdamicyear();
  // this.accordionState =null
  this.router.navigate(['/tabs/home'])
}

ionViewDidLeave(){
  this.getacdamicyear();
  this.selectedYear = null
}

  }


 
  